// 2026 regulated tables and tariff periods, ported from jvanders22/spain-negative-price-alert
// (src/negprice/tariffs.py and retail.py). Values cross-checked in tests/tariffs.test.ts against
// fixtures generated by that Python calculator (scripts/make_xcheck.py).

export type Tariff = "2.0TD" | "3.0TD";

export const SOURCES = {
  peajes: {
    title: "CNMC, Resolución de 18 de diciembre de 2025: peajes de transporte y distribución 2026",
    url: "https://www.boe.es/diario_boe/txt.php?id=BOE-A-2025-26348",
  },
  cargos: {
    title: "Orden TED/1524/2025: cargos del sistema eléctrico y pagos por capacidad 2026",
    url: "https://www.boe.es/diario_boe/txt.php?id=BOE-A-2025-26705",
  },
  periods: {
    title: "CNMC Circular 3/2020, art. 7: periodos horarios (península)",
    url: "https://www.boe.es/buscar/act.php?id=BOE-A-2020-1066",
  },
} as const;

// EUR/kWh by period P1..Pn
export const PEAJE_ENERGY: Record<Tariff, number[]> = {
  "2.0TD": [0.033261, 0.016409, 0.000077],
  "3.0TD": [0.027511, 0.012376, 0.004943, 0.002627, 0.000111, 0.000031],
};
export const CARGO_ENERGY: Record<Tariff, number[]> = {
  "2.0TD": [0.064292, 0.012858, 0.003215],
  "3.0TD": [0.035841, 0.026538, 0.014336, 0.007168, 0.004595, 0.002867],
};
// Pagos por capacidad, EUR/kWh at busbar (only used by the indexed price stack)
export const CAPACITY_ENERGY: Record<Tariff, number[]> = {
  "2.0TD": [0.0008, 0.000133, 0.0],
  "3.0TD": [0.001082, 0.0005, 0.000333, 0.00025, 0.00025, 0.0],
};

// Fixed-date national holidays only (Circular 3/2020 art. 7). [month, day]
export const TARIFF_HOLIDAYS: [number, number][] = [
  [1, 1], [1, 6], [5, 1], [8, 15], [10, 12], [11, 1], [12, 6], [12, 8], [12, 25],
];

const SEASON: Record<number, "A" | "B" | "B1" | "C"> = {
  1: "A", 2: "A", 7: "A", 12: "A", 3: "B", 11: "B", 6: "B1", 8: "B1", 9: "B1", 4: "C", 5: "C", 10: "C",
};
const FIRST_PERIOD = { A: 1, B: 2, B1: 3, C: 4 } as const;

export function isHoliday(month: number, day: number): boolean {
  return TARIFF_HOLIDAYS.some(([m, d]) => m === month && d === day);
}

/** dow: Monday = 0 … Sunday = 6. Returns 1..3 */
export function period20(month: number, day: number, dow: number, hour: number): number {
  if (dow >= 5 || isHoliday(month, day) || hour < 8) return 3;
  return (hour >= 10 && hour < 14) || (hour >= 18 && hour < 22) ? 1 : 2;
}

/** Returns 1..6 */
export function period30(month: number, day: number, dow: number, hour: number): number {
  if (dow >= 5 || isHoliday(month, day) || hour < 8) return 6;
  const peak = (hour >= 9 && hour < 14) || (hour >= 18 && hour < 22);
  return FIRST_PERIOD[SEASON[month]] + (peak ? 0 : 1);
}

export function period(t: Tariff, month: number, day: number, dow: number, hour: number): number {
  return t === "2.0TD" ? period20(month, day, dow, hour) : period30(month, day, dow, hour);
}

/** peaje + cargo, EUR/kWh, for period p (1-based) */
export function regulated(t: Tariff, p: number): number {
  return PEAJE_ENERGY[t][p - 1] + CARGO_ENERGY[t][p - 1];
}

export interface IndexedAssumptions {
  lossFactor: number; // 0.16
  adjustmentEurMwh: number; // 28
  marginEurMwh: number; // 10
}

export const INDEXED_DEFAULTS: IndexedAssumptions = { lossFactor: 0.16, adjustmentEurMwh: 28, marginEurMwh: 10 };

/** Indexed (pass-through) energy price before taxes, EUR/kWh. Same formula as retail.price_stack. */
export function indexedPreTax(t: Tariff, p: number, omieEurMwh: number, a: IndexedAssumptions = INDEXED_DEFAULTS) {
  const cap = CAPACITY_ENERGY[t][p - 1];
  const energy = ((omieEurMwh + a.adjustmentEurMwh + cap * 1000) / 1000) * (1 + a.lossFactor) + a.marginEurMwh / 1000;
  return energy + regulated(t, p);
}

// Taxes. IEE: Ley 38/1992 art. 99.1. IVA 21 % general rate (AEAT). Same values as the calculator.
export const IEE = 0.0511269632;
export const IVA = 0.21;

export function withTaxes(preTax: number, includeIva: boolean): number {
  return preTax * (1 + IEE) * (includeIva ? 1 + IVA : 1);
}
